        process.terminate()
        process.wait()

    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}

import subprocess
import pandas as pd
def task_func(script_path, output_file_path):
    try:
        is_script_path_verified = len(script_path) > 0
        subprocess.run(['python', script_path, output_file_path], check=True, shell=is_script_path_verified)
    except subprocess.CalledProcessError as e:
        raise ValueError(f"Script execution failed: {e}")
    except FileNotFoundError:
        raise ValueError(f"Script not found at {script_path}")

    try:
        df = pd.read_csv(output_file_path)
    except Exception as e:
        raise ValueError(f"Failed to read CSV file: {e}")

    if df.shape[1] != 2:
        raise ValueError("CSV file must contain exactly 2 columns.")

    ax = df.plot.bar(x=df.columns[0], y=df.columns[1], legend=False)
    return df, ax
